import csv
import json
import math
import os

from pyscipopt import Model, quicksum

APP = "/app"
DATA = os.path.join(APP, "data")
SUB = os.path.join(APP, "submissions")
os.makedirs(SUB, exist_ok=True)

# ---------------- Load data ----------------
with open(os.path.join(DATA, "config.json")) as f:
    config = json.load(f)
FEAS_TOL = config.get("feasibility_tolerance", 1e-5)
INT_TOL = config.get("integer_tolerance", 1e-5)
RISK_SCALE = config.get("warranty_risk_cost_scale", 35.0)

lines = {}
with open(os.path.join(DATA, "assembly_lines.csv")) as f:
    for row in csv.DictReader(f):
        lines[row["line_id"]] = {
            "type": row["line_type"],
            "hours": float(row["available_hours"]),
            "cost_per_hour": float(row["variable_cost_per_hour"]),
        }

orders = {}
order_list = []
with open(os.path.join(DATA, "pack_orders.csv")) as f:
    for row in csv.DictReader(f):
        oid = row["order_id"]
        orders[oid] = {
            "family": row["pack_family"],
            "chem": row["chemistry"],
            "requested": int(row["requested_packs"]),
            "cells_per_pack": int(row["cells_per_pack"]),
            "min_soh": float(row["min_avg_soh"]),
            "min_safety": float(row["min_avg_safety_score"]),
            "revenue": float(row["revenue_per_pack"]),
            "fill_rate": float(row["minimum_fill_rate"]),
        }
        order_list.append(oid)

lots = {}
with open(os.path.join(DATA, "cell_lots.csv")) as f:
    for row in csv.DictReader(f):
        kid = row["lot_id"]
        lots[kid] = {
            "chem": row["chemistry"],
            "cells": int(row["available_cells"]),
            "soh": float(row["state_of_health"]),
            "safety": float(row["safety_score"]),
            "cost": float(row["cell_cost"]),
            "warranty": float(row["warranty_factor"]),
        }

elig = {}
with open(os.path.join(DATA, "line_family_eligibility.csv")) as f:
    for row in csv.DictReader(f):
        key = (row["line_id"], row["pack_family"])
        elig[key] = {
            "setup_hours": float(row["setup_hours"]),
            "setup_cost": float(row["setup_cost"]),
            "base_hours": float(row["base_hours_per_pack"]),
        }

pairings = []
with open(os.path.join(DATA, "lot_order_compatibility.csv")) as f:
    for row in csv.DictReader(f):
        oid, kid = row["order_id"], row["lot_id"]
        if orders[oid]["chem"] != lots[kid]["chem"]:
            continue
        pairings.append({
            "order": oid,
            "lot": kid,
            "max_packs": int(row["max_packs"]),
            "test_cost": float(row["test_cost_per_pack"]),
            "hours_mult": float(row["hours_multiplier"]),
        })

# ---------------- Build model ----------------
model = Model("second_life_battery_pack_assembly")
model.setParam("gaprel", 0.0005)

time_limit = 300.0
env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
if env_limit is not None:
    try:
        time_limit = min(time_limit, float(env_limit))
    except ValueError:
        pass
model.setParam("limits/time", time_limit)

s_vars = {}
for (l, fam), e in elig.items():
    s_vars[(l, fam)] = model.addVar(name=f"s_{l}_{fam}", vtype="B", lb=0.0, ub=1.0, obj=0.0)

x_vars = {}
for p in pairings:
    oid, kid = p["order"], p["lot"]
    fam = orders[oid]["family"]
    for l in lines:
        if (l, fam) not in elig:
            continue
        M = p["max_packs"]
        e = elig[(l, fam)]
        o = orders[oid]
        k = lots[kid]
        obj = (
            o["revenue"]
            - o["cells_per_pack"] * k["cost"]
            - p["test_cost"]
            - RISK_SCALE * k["warranty"]
            - lines[l]["cost_per_hour"] * e["base_hours"] * p["hours_mult"]
        )
        x_vars[(l, oid, kid)] = model.addVar(
            name=f"x_{l}_{oid}_{kid}", vtype="I", lb=0.0, ub=float(M), obj=obj
        )

# Setup gating + pairing cap (cap already in ub)
for p in pairings:
    oid, kid = p["order"], p["lot"]
    fam = orders[oid]["family"]
    M = p["max_packs"]
    for l in lines:
        if (l, fam) not in elig:
            continue
        v = x_vars[(l, oid, kid)]
        model.addCons(v <= M * s_vars[(l, fam)], name=f"gate_{l}_{oid}_{kid}")

# Order demand cap + min fill
for oid in order_list:
    o = orders[oid]
    xs = [x_vars[(l, oid, kid)] for (l, oid2, kid) in x_vars if oid2 == oid]
    model.addCons(quicksum(xs) <= o["requested"], name=f"demand_{oid}")
    minfill = math.ceil(o["fill_rate"] * o["requested"] - 1e-9)
    model.addCons(quicksum(xs) >= minfill, name=f"minfill_{oid}")

# Lot cell availability
for kid, k in lots.items():
    cons_terms = []
    for (l, oid2, kid2), v in x_vars.items():
        if kid2 == kid:
            cons_terms.append(orders[oid2]["cells_per_pack"] * v)
    if cons_terms:
        model.addCons(quicksum(cons_terms) <= k["cells"], name=f"lot_{kid}")

# Quality weighted averages (linearized)
for oid in order_list:
    o = orders[oid]
    xs = [(x_vars[(l, oid, kid)], kid) for (l, oid2, kid) in x_vars if oid2 == oid]
    if not xs:
        continue
    model.addCons(
        quicksum(v * lots[kid]["soh"] for v, kid in xs)
        >= o["min_soh"] * quicksum(v for v, _ in xs),
        name=f"soh_{oid}",
    )
    model.addCons(
        quicksum(v * lots[kid]["safety"] for v, kid in xs)
        >= o["min_safety"] * quicksum(v for v, _ in xs),
        name=f"safety_{oid}",
    )

# Line capacity
for l, L in lines.items():
    setup_terms = [e["setup_hours"] * s_vars[(l, fam)] for (l2, fam), e in elig.items() if l2 == l]
    build_terms = []
    for (l2, oid, kid), v in x_vars.items():
        if l2 == l:
            e = elig[(l, orders[oid]["family"])]
            p = next(p for p in pairings if p["order"] == oid and p["lot"] == kid)
            build_terms.append(e["base_hours"] * p["hours_mult"] * v)
    model.addCons(
        quicksum(setup_terms) + quicksum(build_terms) <= L["hours"], name=f"cap_{l}"
    )

model.setObjective(
    quicksum(v.obj for v in s_vars.values()) + quicksum(v.obj for v in x_vars.values()),
    sense="maximize",
)

# ---------------- Solve ----------------
model.optimize()
status = model.getStatus()
print("Solver status:", status)
nsols = model.getNSols()
print("Number of solutions:", nsols)

best = model.getBestSol()
if best is None:
    # Fallback: write empty plan (should not happen for this instance)
    with open(os.path.join(SUB, "solution.csv"), "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["row_type", "line_id", "order_id", "lot_id", "value"])
    raise SystemExit("No solution found; wrote empty solution.csv")

obj_val = model.getObjVal()
print("Objective (contribution margin):", obj_val)

# ---------------- Extract and validate ----------------
s_val = {}
for key, v in s_vars.items():
    s_val[key] = int(round(model.getVal(v)))
x_val = {}
for key, v in x_vars.items():
    x_val[key] = int(round(model.getVal(v)))

errors = []
# integrality already enforced by rounding; check closeness
for key, v in x_vars.items():
    if abs(model.getVal(v) - x_val[key]) > INT_TOL:
        errors.append(f"integrality {key}")
for key, v in s_vars.items():
    if abs(model.getVal(v) - s_val[key]) > INT_TOL:
        errors.append(f"integrality {key}")

# demand / min fill
for oid in order_list:
    o = orders[oid]
    tot = sum(x_val[(l, oid, kid)] for (l, o2, kid) in x_val if o2 == oid)
    if tot > o["requested"] + FEAS_TOL:
        errors.append(f"demand cap {oid}: {tot}")
    minfill = math.ceil(o["fill_rate"] * o["requested"] - 1e-9)
    if tot + FEAS_TOL < minfill:
        errors.append(f"min fill {oid}: {tot} < {minfill}")
    # quality
    if tot > 0:
        soh = sum(x_val[(l, oid, kid)] * lots[kid]["soh"] for (l, o2, kid) in x_val if o2 == oid) / tot
        saf = sum(x_val[(l, oid, kid)] * lots[kid]["safety"] for (l, o2, kid) in x_val if o2 == oid) / tot
        if soh + FEAS_TOL < o["min_soh"]:
            errors.append(f"soh {oid}: {soh}")
        if saf + FEAS_TOL < o["min_safety"]:
            errors.append(f"safety {oid}: {saf}")

# pairing caps and gating
for (l, oid, kid), val in x_val.items():
    p = next(p for p in pairings if p["order"] == oid and p["lot"] == kid)
    if val > p["max_packs"] + FEAS_TOL:
        errors.append(f"pairing cap {l},{oid},{kid}: {val}")
    fam = orders[oid]["family"]
    if val > 0 and s_val.get((l, fam), 0) != 1:
        errors.append(f"gating {l},{oid},{kid} without setup")

# lot availability
for kid, k in lots.items():
    used = sum(orders[oid]["cells_per_pack"] * x_val[(l, oid, kid)] for (l, oid, k2) in x_val if k2 == kid)
    if used > k["cells"] + FEAS_TOL:
        errors.append(f"lot cells {kid}: {used} > {k['cells']}")

# line capacity
for l, L in lines.items():
    hours = sum(e["setup_hours"] * s_val[(l, fam)] for (l2, fam), e in elig.items() if l2 == l)
    for (l2, oid, kid), val in x_val.items():
        if l2 == l and val > 0:
            e = elig[(l, orders[oid]["family"])]
            p = next(p for p in pairings if p["order"] == oid and p["lot"] == kid)
            hours += e["base_hours"] * p["hours_mult"] * val
    if hours > L["hours"] + FEAS_TOL:
        errors.append(f"line hours {l}: {hours} > {L['hours']}")

print("Validation errors:", errors if errors else "none")

# ---------------- Write solution ----------------
with open(os.path.join(SUB, "solution.csv"), "w", newline="") as f:
    w = csv.writer(f)
    w.writerow(["row_type", "line_id", "order_id", "lot_id", "value"])
    for (l, fam), val in s_val.items():
        if val > 0:
            w.writerow(["setup", l, fam, "", f"{val:.8f}"])
    for (l, oid, kid), val in x_val.items():
        if val > 0:
            w.writerow(["build", l, oid, kid, f"{val:.8f}"])

print("Wrote", os.path.join(SUB, "solution.csv"))
model.free()
